def check_occurences(lst):
    result = {}
    for item in lst:
        key = tuple(sorted(item))
        result[key] = result.get(key, 0) + 1
    return result

assert check_occurences([(3, 1), (1, 3), (2, 5), (5, 2), (6, 3)]) == {(1, 3): 2, (2, 5): 2, (3, 6): 1}
